    pub(crate) plan: BenchmarkCampaignPlan,
    pub(crate) plan_fingerprint: String,
    pub(crate) state: BenchmarkCampaignState,
    pub(crate) runs: Vec<CampaignRunProgress>,
    pub(crate) created_unix_ms: u64,
    pub(crate) updated_unix_ms: u64,
}

impl BenchmarkCampaign {
    pub(crate) fn new(plan: BenchmarkCampaignPlan) -> Result<Self, String> {
        let plan_fingerprint = plan.fingerprint()?;
        let runs = plan
            .schedule()?
            .into_iter()
            .map(|schedule| CampaignRunProgress {
                schedule,
                status: CampaignRunStatus::Pending,
                pre_measurement_retries: 0,
                record: None,
                failure: None,
            })
            .collect();
        let now = unix_ms();
        Ok(Self {
            schema_version: CAMPAIGN_SCHEMA_VERSION,
            plan,
            plan_fingerprint,
            state: BenchmarkCampaignState::Draft,
            runs,
            created_unix_ms: now,
            updated_unix_ms: now,
        })
    }

    pub(crate) fn preflight(
        &self,
        installed: &[CampaignRepresentation],
    ) -> Result<CampaignPreflight, String> {
        self.plan.validate()?;
        let mut missing = Vec::new();
        let mut transfer = 0_u64;
        let mut storage = 0_u64;
        for candidate in &self.plan.candidates {
            if installed.contains(&candidate.representation) {
                continue;
            }
            let source_reference = required_source_field(
                candidate.source.source_reference.as_deref(),
                &candidate.representation.model_id,
                "source",
            )?;
            let license = required_source_field(
                candidate.source.license.as_deref(),
                &candidate.representation.model_id,
                "license",
            )?;
            let expected_sha256 = required_source_field(
                candidate.source.expected_sha256.as_deref(),
                &candidate.representation.model_id,
                "SHA-256",
            )?;
            if expected_sha256 != candidate.representation.model_version {
                return Err(format!(
                    "candidate `{}` source SHA-256 does not match frozen model version",
                    candidate.representation.model_id
                ));
            }
            let transfer_size_bytes = candidate.source.transfer_size_bytes.ok_or_else(|| {
                format!("missing transfer size for `{}`", candidate.representation.model_id)
            })?;
            let storage_size_bytes = candidate.source.storage_size_bytes.ok_or_else(|| {
                format!("missing storage size for `{}`", candidate.representation.model_id)
            })?;
            transfer = transfer.saturating_add(transfer_size_bytes);
            storage = storage.saturating_add(storage_size_bytes);
            missing.push(CampaignMissingCandidate {
                representation: candidate.representation.clone(),
                source_reference,
                license,
                expected_sha256,
                transfer_size_bytes,
                storage_size_bytes,
            });
        }
        Ok(CampaignPreflight {
            plan_fingerprint: self.plan_fingerprint.clone(),
            missing,
            total_transfer_size_bytes: transfer,
            total_storage_size_bytes: storage,
        })
    }

    pub(crate) fn validate_download_approval(
        &self,
        preflight: &CampaignPreflight,
        approval: &CampaignDownloadApproval,
    ) -> Result<(), String> {
        if preflight.plan_fingerprint != self.plan_fingerprint
            || approval.plan_fingerprint != self.plan_fingerprint
        {
            return Err("download approval does not belong to the frozen campaign".to_owned());
        }
        let expected = preflight
            .missing
            .iter()
            .map(|missing| missing.representation.clone())
            .collect::<Vec<_>>();
        if approval.approved_missing != expected {
            return Err("download approval must match the exact missing candidate set".to_owned());
        }
        Ok(())
    }

    pub(crate) fn start(&mut self, verified: &[CampaignRepresentation]) -> Result<(), String> {
        if self.state != BenchmarkCampaignState::Draft {
            return Err("campaign can only start from Draft".to_owned());
        }
        self.plan.validate()?;
        for candidate in &self.plan.candidates {
            if !verified.contains(&candidate.representation) {
                return Err(format!(
                    "candidate `{}` was not content-verified before campaign start",
                    candidate.representation.model_id
                ));
            }
        }
        self.state = BenchmarkCampaignState::Running;
        self.touch();
        Ok(())
    }

    pub(crate) fn begin_next_run(&mut self) -> Result<Option<CampaignRunRequest>, String> {
        if self.state != BenchmarkCampaignState::Running {
            return Ok(None);
        }
        if self.has_active_run() {
            return Err("measured local campaign execution is sequential".to_owned());
        }
        let Some(index) = self
            .runs
            .iter()
            .position(|run| run.status == CampaignRunStatus::Pending)
        else {
            self.state = BenchmarkCampaignState::Completed;
            self.touch();
            return Ok(None);
        };
        self.runs[index].status = CampaignRunStatus::Preparing;
        let request = self.run_request(self.runs[index].schedule.clone())?;
        self.touch();
        Ok(Some(request))
    }

    pub(crate) fn preparing_run_request(&self) -> Result<Option<CampaignRunRequest>, String> {
        self.request_for_status(
            CampaignRunStatus::Preparing,
            "campaign persistence contains multiple preparing runs",
        )
    }

    pub(crate) fn running_run_request(&self) -> Result<Option<CampaignRunRequest>, String> {
        self.request_for_status(
            CampaignRunStatus::Running,
            "campaign persistence contains multiple measured runs",
        )
    }

    fn request_for_status(
        &self,
        status: CampaignRunStatus,
        duplicate_message: &str,
    ) -> Result<Option<CampaignRunRequest>, String> {
        let matches = self
            .runs
            .iter()
            .filter(|run| run.status == status)
            .collect::<Vec<_>>();
        if matches.len() > 1 {
            return Err(duplicate_message.to_owned());
        }
        matches
            .first()
            .map(|run| self.run_request(run.schedule.clone()))
            .transpose()
    }

    fn run_request(
        &self,
        schedule: CampaignScheduleEntry,
    ) -> Result<CampaignRunRequest, String> {
        let candidate = self
            .plan
            .candidates
            .get(schedule.candidate_index)
            .ok_or_else(|| "campaign candidate index is invalid".to_owned())?;
        let task = self
            .plan
            .tasks
            .get(schedule.task_index)
            .ok_or_else(|| "campaign task index is invalid".to_owned())?;
        let runtime = self
            .plan
            .environment_identity(schedule.execution_environment)?;
        let reset_hash = stable_hash(
            format!(
                "{}:{}:{}:{}:{}",
                self.plan_fingerprint,
                schedule.task_id,
                schedule.repetition,
                schedule.candidate_index,
                schedule.execution_environment.identity()
            )
            .as_bytes(),
        );
        Ok(CampaignRunRequest {
            campaign_fingerprint: self.plan_fingerprint.clone(),
            schedule: schedule.clone(),
            model: candidate
                .representation
                .model_identity(&runtime.backend_runtime_version),
            representation: candidate.representation.clone(),
            fixture: task.fixture.clone(),
            candidate_contract: task.fixture.candidate_contract(&schedule.task_id)?,
            harness: campaign_task_harness(&schedule.task_id)?,
            reset_instance_id: format!("run-{reset_hash:016x}"),
        })
    }

    pub(crate) fn mark_measurement_started(
        &mut self,
        request: &CampaignRunRequest,
    ) -> Result<(), String> {
        self.validate_request(request, CampaignRunStatus::Preparing)?;
        self.runs[request.schedule.ordinal as usize].status = CampaignRunStatus::Running;
        self.touch();
        Ok(())
    }

    pub(crate) fn record_pre_measurement_failure(
        &mut self,
        request: &CampaignRunRequest,
    ) -> Result<PreMeasurementFailureDisposition, String> {
        self.validate_request(request, CampaignRunStatus::Preparing)?;
        let run = &mut self.runs[request.schedule.ordinal as usize];
        run.pre_measurement_retries = run.pre_measurement_retries.saturating_add(1);
        let disposition = if run.pre_measurement_retries <= MAX_PRE_MEASUREMENT_RETRIES {
            run.status = CampaignRunStatus::Pending;
            PreMeasurementFailureDisposition::Retry
        } else {
            run.status = CampaignRunStatus::Failed;
            run.failure = Some(CampaignFailureKind::InfrastructurePreMeasurement);
            PreMeasurementFailureDisposition::Exhausted
        };
        self.touch();
        Ok(disposition)
    }

    pub(crate) fn complete_run(
        &mut self,
        request: &CampaignRunRequest,
        record: BenchmarkRecord,
    ) -> Result<(), String> {
        let record = self.validate_and_attach_record(request, record)?;
        let run = &mut self.runs[request.schedule.ordinal as usize];
        run.status = CampaignRunStatus::Completed;
        run.record = Some(record);
        self.touch();
        Ok(())
    }

    pub(crate) fn fail_measured_run(
        &mut self,
        request: &CampaignRunRequest,
        failure: CampaignFailureKind,
    ) -> Result<(), String> {
        self.fail_measured_run_with_record(request, failure, None)
    }

    pub(crate) fn fail_measured_run_with_record(
        &mut self,
        request: &CampaignRunRequest,
        failure: CampaignFailureKind,
        record: Option<BenchmarkRecord>,
    ) -> Result<(), String> {
        if failure == CampaignFailureKind::InfrastructurePreMeasurement {
            return Err(
                "pre-measurement infrastructure failures use the bounded retry path".to_owned(),
            );
        }
        self.validate_request(request, CampaignRunStatus::Running)?;
        let record = record
            .map(|record| self.validate_and_attach_record(request, record))
            .transpose()?;
        let run = &mut self.runs[request.schedule.ordinal as usize];
        run.status = CampaignRunStatus::Failed;
        run.failure = Some(failure);
        run.record = record;
        self.touch();
        Ok(())
    }

    fn validate_and_attach_record(
        &mut self,
        request: &CampaignRunRequest,
        mut record: BenchmarkRecord,
    ) -> Result<BenchmarkRecord, String> {
        self.validate_request(request, CampaignRunStatus::Running)?;
        let task_plan = &self.plan.tasks[request.schedule.task_index];
        let descriptor = benchmark_task(&request.schedule.task_id)
            .ok_or_else(|| "frozen campaign task descriptor is unavailable".to_owned())?;
        let expected_completion_criteria = descriptor
            .completion_criteria
            .iter()
            .map(|criterion| (*criterion).to_owned())
            .collect::<Vec<_>>();
        if record.schema_version != BENCHMARK_SCHEMA_VERSION
            || record.identity.corpus_version != self.plan.corpus_version
            || record.identity.harness_version != self.plan.benchmark_harness_version
            || record.identity.runtime_harness_version != task_plan.runtime_harness_version
            || record.identity.model != request.model
            || record.identity.task_id != request.schedule.task_id
            || record.identity.hardware != self.plan.hardware
            || record.identity.quality != self.plan.quality
            || record.identity.workload_policy_version != self.plan.workload_policy_version
            || record.identity.observed_workload != TelemetryValue::Measured(task_plan.workload)
            || record.identity.tool_budget != task_plan.tool_budget
            || record.identity.completion_criteria != expected_completion_criteria
            || record.identity.execution.is_some()
        {
            self.reject_run(request, CampaignFailureKind::IdentityMismatch)?;
            return Err("automatic campaign evidence identity mismatch".to_owned());
        }
        record.identity.execution = Some(BenchmarkExecutionIdentity {
            campaign_harness_version: self.plan.campaign_harness_version.clone(),
            schedule_policy_version: self.plan.schedule_version.clone(),
            comparison_class: self.plan.comparison_class.identity().to_owned(),
            execution_profile: self.plan.execution_profile.identity().to_owned(),
            execution_environment: request.schedule.execution_environment.identity().to_owned(),
            fixture_id: request.fixture.fixture_id.clone(),
            fixture_version: request.fixture.fixture_version.clone(),
            fixture_instance_id: request.fixture.instance_id.clone(),
            sampling_profile: self.plan.sampling_profile.clone(),
            seed_policy: self.plan.seed_policy.identity(),
        });
        Ok(record)
    }

    pub(crate) fn pause(&mut self) -> Result<(), String> {
        if self.state != BenchmarkCampaignState::Running || self.has_active_run() {
            return Err("campaign pause is allowed only at a run boundary".to_owned());
        }
        self.state = BenchmarkCampaignState::Paused;
        self.touch();
        Ok(())
    }

    pub(crate) fn stop(&mut self) -> Result<(), String> {
        if self.has_active_run() {
            return Err("campaign stop is allowed only after active work is cleaned up".to_owned());
        }
        if matches!(
            self.state,
            BenchmarkCampaignState::Completed | BenchmarkCampaignState::Incompatible
        ) {
            return Err("terminal campaign cannot be stopped".to_owned());
        }
        self.state = BenchmarkCampaignState::Stopped;
        self.touch();
        Ok(())
    }

    pub(crate) fn resume(
        &mut self,
        current: CampaignResumeIdentity,
    ) -> Result<(), String> {
        if !matches!(
            self.state,
            BenchmarkCampaignState::Paused | BenchmarkCampaignState::Stopped
        ) {
            return Err("campaign is not paused or stopped".to_owned());
        }
        if current != self.plan.resume_identity() {
            self.state = BenchmarkCampaignState::Incompatible;
            self.touch();
            return Err("campaign environment drift requires a new derived campaign".to_owned());
        }
        self.state = BenchmarkCampaignState::Running;
        self.touch();
        Ok(())
    }

    pub(crate) fn completed_records(&self) -> Vec<&BenchmarkRecord> {
        self.runs
            .iter()
            .filter_map(|run| run.record.as_ref())
            .collect()
    }

    pub(crate) fn report(&self) -> CampaignReport {
        CampaignReport::from_campaign(self)
    }

    fn validate_request(
        &self,
        request: &CampaignRunRequest,
        expected_status: CampaignRunStatus,
    ) -> Result<(), String> {
        if request.campaign_fingerprint != self.plan_fingerprint {
            return Err("run request belongs to another campaign".to_owned());
        }
        let Some(run) = self.runs.get(request.schedule.ordinal as usize) else {
            return Err("run request ordinal is outside the frozen schedule".to_owned());
        };
        if run.schedule != request.schedule || run.status != expected_status {
            return Err("run request is stale for the current campaign state".to_owned());
        }
        Ok(())
    }

    fn reject_run(
        &mut self,
        request: &CampaignRunRequest,
        failure: CampaignFailureKind,
    ) -> Result<(), String> {
        self.validate_request(request, CampaignRunStatus::Running)?;
        let run = &mut self.runs[request.schedule.ordinal as usize];
        run.status = CampaignRunStatus::Rejected;
        run.failure = Some(failure);
        self.touch();
        Ok(())
    }

    fn has_active_run(&self) -> bool {
        self.runs.iter().any(|run| {
            matches!(
                run.status,
                CampaignRunStatus::Preparing | CampaignRunStatus::Running
            )
        })
    }

    fn touch(&mut self) {
        self.updated_unix_ms = unix_ms();
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CampaignCandidateReport {
    pub(crate) model_id: String,
    pub(crate) attempted: u64,
    pub(crate) successful: u64,
    pub(crate) failed: u64,
    pub(crate) rejected: u64,
    pub(crate) oom_count: u64,
    pub(crate) median_success_elapsed_ms: TelemetryValue<u64>,
    pub(crate) median_generation_tokens_per_second_milli: TelemetryValue<u64>,
    pub(crate) median_load_latency_ms: TelemetryValue<u64>,
    pub(crate) peak_backend_gpu_memory_bytes: TelemetryValue<u64>,
    pub(crate) validation_attempts: u64,
    pub(crate) repair_loops: u64,
    pub(crate) human_interventions: u64,
    pub(crate) per_task: BTreeMap<String, CampaignTaskReport>,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub(crate) struct CampaignTaskReport {
    pub(crate) attempted: u64,
    pub(crate) successful: u64,
    pub(crate) failed: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct CampaignReport {
    pub(crate) comparison_class: CampaignComparisonClass,
    pub(crate) candidates: Vec<CampaignCandidateReport>,
}

impl CampaignReport {
    fn from_campaign(campaign: &BenchmarkCampaign) -> Self {
        let candidates = campaign
            .plan
            .candidates
            .iter()
            .enumerate()
            .map(|(candidate_index, candidate)| {
                let runs = campaign
                    .runs
                    .iter()
                    .filter(|run| run.schedule.candidate_index == candidate_index)
                    .collect::<Vec<_>>();
                let attempted = runs
                    .iter()
                    .filter(|run| {
                        matches!(
                            run.status,
                            CampaignRunStatus::Completed
                                | CampaignRunStatus::Failed
                                | CampaignRunStatus::Rejected
                        )
                    })
                    .count() as u64;
                let successful = runs
                    .iter()
                    .filter(|run| run.status == CampaignRunStatus::Completed)
                    .count() as u64;
                let failed = runs
                    .iter()
                    .filter(|run| run.status == CampaignRunStatus::Failed)
                    .count() as u64;
                let rejected = runs
                    .iter()
                    .filter(|run| run.status == CampaignRunStatus::Rejected)
                    .count() as u64;
                let oom_count = runs
                    .iter()
                    .filter(|run| run.failure == Some(CampaignFailureKind::OutOfMemory))
                    .count() as u64;
                let records = runs
                    .iter()
                    .filter_map(|run| run.record.as_ref())
                    .collect::<Vec<_>>();
                let mut per_task = BTreeMap::<String, CampaignTaskReport>::new();
                for run in &runs {
                    if matches!(
                        run.status,
                        CampaignRunStatus::Completed
                            | CampaignRunStatus::Failed
                            | CampaignRunStatus::Rejected
                    ) {
                        let task = per_task.entry(run.schedule.task_id.clone()).or_default();
                        task.attempted = task.attempted.saturating_add(1);
                        if run.status == CampaignRunStatus::Completed {
                            task.successful = task.successful.saturating_add(1);
                        } else {
                            task.failed = task.failed.saturating_add(1);
                        }
                    }
                }
                CampaignCandidateReport {
                    model_id: candidate.representation.model_id.clone(),
                    attempted,
                    successful,
                    failed,
                    rejected,
                    oom_count,
                    median_success_elapsed_ms: median_measured(
                        records
                            .iter()
                            .filter(|record| measured_bool(&record.metrics.completion_success))
                            .filter_map(|record| measured_u64(&record.metrics.elapsed_ms))
                            .collect(),
                    ),
                    median_generation_tokens_per_second_milli: median_measured(
                        records
                            .iter()
                            .filter_map(|record| {
                                measured_u64(
                                    &record.metrics.generation_tokens_per_second_milli,
                                )
                            })
                            .collect(),
                    ),
                    median_load_latency_ms: median_measured(
                        records
                            .iter()
                            .filter_map(|record| measured_u64(&record.metrics.load_latency_ms))
                            .collect(),
                    ),
                    peak_backend_gpu_memory_bytes: max_measured(
                        records
                            .iter()
                            .filter_map(|record| {
                                measured_u64(&record.metrics.peak_backend_gpu_memory_bytes)
                            })
                            .collect(),
                    ),
                    validation_attempts: records
                        .iter()
                        .filter_map(|record| measured_u64(&record.metrics.validation_attempts))
                        .sum(),
                    repair_loops: records
                        .iter()
                        .filter_map(|record| measured_u64(&record.metrics.repair_loops))
                        .sum(),
                    human_interventions: records
                        .iter()
                        .filter_map(|record| measured_u64(&record.metrics.human_interventions))
                        .sum(),
                    per_task,
                }
            })
            .collect();
        Self {
            comparison_class: campaign.plan.comparison_class,
            candidates,
        }
    }
}

pub(crate) struct BenchmarkCampaignStore {
    root: PathBuf,
}

impl BenchmarkCampaignStore {
    pub(crate) fn open(root: PathBuf) -> Result<Self, String> {
        fs::create_dir_all(&root).map_err(|error| error.to_string())?;
        Ok(Self { root })
    }

    pub(crate) fn save(&self, campaign: &BenchmarkCampaign) -> Result<PathBuf, String> {
        let bytes = serde_json::to_vec_pretty(campaign).map_err(|error| error.to_string())?;
        let path = self.root.join(format!("{}.json", campaign.plan_fingerprint));
        let temporary = self
            .root
            .join(format!("{}.json.tmp", campaign.plan_fingerprint));
        fs::write(&temporary, bytes).map_err(|error| error.to_string())?;
        replace_campaign_file(&temporary, &path)?;
        Ok(path)
    }

    pub(crate) fn load_latest(&self) -> Result<Option<BenchmarkCampaign>, String> {
        let mut latest: Option<BenchmarkCampaign> = None;
        for entry in fs::read_dir(&self.root).map_err(|error| error.to_string())? {
            let entry = entry.map_err(|error| error.to_string())?;
            let path = entry.path();
            if path.extension().and_then(|value| value.to_str()) != Some("json") {
                continue;
            }
            let bytes = fs::read(&path).map_err(|error| error.to_string())?;
            let campaign = serde_json::from_slice::<BenchmarkCampaign>(&bytes)
                .map_err(|error| error.to_string())?;
            if campaign.schema_version != CAMPAIGN_SCHEMA_VERSION
                || campaign.plan_fingerprint != campaign.plan.fingerprint()?
            {
                return Err("persisted campaign identity is incompatible or corrupted".to_owned());
            }
            if latest
                .as_ref()
                .is_none_or(|current| campaign.updated_unix_ms > current.updated_unix_ms)
            {
                latest = Some(campaign);
            }
        }
        Ok(latest)
    }
}

fn replace_campaign_file(temporary: &Path, path: &Path) -> Result<(), String> {
    let backup = path.with_extension("json.bak");
    if backup.exists() {
        fs::remove_file(&backup).map_err(|error| error.to_string())?;
    }
    let had_existing = path.exists();
    if had_existing {
        fs::rename(path, &backup).map_err(|error| error.to_string())?;
    }
    match fs::rename(temporary, path) {
        Ok(()) => {
            if had_existing {
                let _ = fs::remove_file(backup);
            }
            Ok(())
        }
        Err(error) => {
            if had_existing {
                let _ = fs::rename(&backup, path);
            }
            Err(error.to_string())
        }
    }
}

fn required_source_field(
    value: Option<&str>,
    model_id: &str,
    label: &str,
) -> Result<String, String> {
    value
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned)
        .ok_or_else(|| format!("missing {label} for `{model_id}`"))
}

fn candidate_prompt(kind: BenchmarkTaskKind, marker: &str) -> String {
    let instruction = match kind {
        BenchmarkTaskKind::ReadQuestion => {
            "Answer the requested project question using normal read/provenance retrieval and cite the project evidence you used."
        }
        BenchmarkTaskKind::ProjectInspection => {
            "Inspect the requested fixture state through governed read-only production tools. Do not mutate project or code state."
        }
        BenchmarkTaskKind::CodeImplementation => {
            "Implement the requested code correction in the managed code workspace, then return control for engine-managed validation and reviewed apply."
        }
        BenchmarkTaskKind::TypedAuthoringMutation => {
            "Perform the requested persisted scene mutation through typed Editor MCP authoring tools, not direct file replacement."
        }
        BenchmarkTaskKind::ValidationRepair => {
            "Repair the engine-reported validation failure in the managed code workspace and return control for validation."
        }
        BenchmarkTaskKind::RuntimeInteraction => {
            "Use normal managed Play and ADR 0157 deterministic fixed-tick runtime input to exercise the requested interaction."
        }
        BenchmarkTaskKind::VisualEvaluation => {
            "Use normal managed Play, host-owned frame capture, and the verified image-input route when available. Never claim visual inspection without a host frame."
        }
    };
    format!("{instruction} Fixture instance marker: {marker}.")
}

fn hardware_exact(hardware: &BenchmarkHardwareIdentity) -> bool {
    !hardware.platform.trim().is_empty()
        && matches!(&hardware.gpu, TelemetryValue::Measured(value) if !value.trim().is_empty())
        && matches!(hardware.total_gpu_memory_bytes, TelemetryValue::Measured(value) if value > 0)
        && matches!(hardware.total_system_memory_bytes, TelemetryValue::Measured(value) if value > 0)
}

fn measured_text(value: &TelemetryValue<String>) -> Option<String> {
    match value {
        TelemetryValue::Measured(value) if !value.trim().is_empty() => Some(value.clone()),
        _ => None,
    }
}

fn measured_u64(value: &TelemetryValue<u64>) -> Option<u64> {
    match value {
        TelemetryValue::Measured(value) => Some(*value),
        TelemetryValue::Unavailable => None,
    }
}

fn measured_bool(value: &TelemetryValue<bool>) -> bool {
    matches!(value, TelemetryValue::Measured(true))
}

fn median_measured(mut values: Vec<u64>) -> TelemetryValue<u64> {
    if values.is_empty() {
        return TelemetryValue::Unavailable;
    }
    values.sort_unstable();
    TelemetryValue::Measured(values[values.len() / 2])
}

fn max_measured(values: Vec<u64>) -> TelemetryValue<u64> {
    values
        .into_iter()
        .max()
        .map(TelemetryValue::Measured)
        .unwrap_or(TelemetryValue::Unavailable)
}

fn stable_hash(bytes: &[u8]) -> u64 {
    stable_hash_seed(bytes, 0xcbf2_9ce4_8422_2325)
}

fn stable_hash_seed(bytes: &[u8], seed: u64) -> u64 {
    bytes.iter().fold(seed, |hash, byte| {
        (hash ^ u64::from(*byte)).wrapping_mul(0x0000_0100_0000_01b3)
    })
}

fn unix_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hardware() -> BenchmarkHardwareIdentity {
        BenchmarkHardwareIdentity {
            platform: "windows-x86_64".to_owned(),
            gpu: TelemetryValue::Measured("Fixture GPU".to_owned()),
            total_gpu_memory_bytes: TelemetryValue::Measured(12 * 1024 * 1024 * 1024),
            total_system_memory_bytes: TelemetryValue::Measured(32 * 1024 * 1024 * 1024),
        }
    }

    fn candidate(name: &str) -> CampaignCandidate {
        CampaignCandidate {
            representation: CampaignRepresentation {
                backend_id: "gameengine-managed-llama-cpp".to_owned(),
                model_id: name.to_owned(),
                model_version: format!("{name:0<64}"),
                quantization: "Q4_K_M".to_owned(),
                representation_size_bytes: 4_000_000_000,
            },
            source: CampaignCandidateSource::installed(),
        }
    }

    fn plan() -> BenchmarkCampaignPlan {
        BenchmarkCampaignPlan {
            schema_version: CAMPAIGN_SCHEMA_VERSION,
            corpus_version: BENCHMARK_CORPUS_VERSION.to_owned(),
            benchmark_harness_version: BENCHMARK_HARNESS_VERSION.to_owned(),
            campaign_harness_version: CAMPAIGN_HARNESS_VERSION.to_owned(),
            schedule_version: CAMPAIGN_SCHEDULE_VERSION.to_owned(),
            candidates: vec![candidate("model-a"), candidate("model-b")],
            tasks: crate::agent_benchmark::BENCHMARK_TASKS
                .iter()
                .enumerate()
                .map(|(index, task)| {
                    CampaignTaskPlan::for_task(task.id, 0x1560 + index as u64)
                        .expect("task plan")
                })
                .collect(),
            repetitions: 2,
            comparison_class: CampaignComparisonClass::ModelComparison,
            execution_profile: CampaignExecutionProfile::Warm,
            execution_environments: vec![CampaignEnvironmentIdentity {
                environment: CampaignExecutionEnvironment::WindowsNative,
                backend_runtime_version: "llama.cpp:b1@rev;env=windows_native".to_owned(),
            }],
            quality: QualityPreference::Balanced,
            hardware: hardware(),
            workload_policy_version: WORKLOAD_POLICY_VERSION.to_owned(),
            sampling_profile: "provider-default-uncontrolled".to_owned(),
            seed_policy: CampaignSeedPolicy::ProviderUnavailable,
        }
    }

    #[test]
    fn seven_tasks_map_to_authoritative_production_harnesses() {
        let mappings = crate::agent_benchmark::BENCHMARK_TASKS
            .iter()
            .map(|task| (task.kind, campaign_task_harness(task.id).expect("mapping")))
            .collect::<Vec<_>>();
        assert_eq!(mappings[0].1, CampaignTaskHarness::NativeReadQuestion);
        assert!(mappings[1..5]
            .iter()
            .all(|(_, harness)| *harness == CampaignTaskHarness::GovernedAgentHost));
        assert!(mappings[5..]
            .iter()
            .all(|(_, harness)| *harness == CampaignTaskHarness::ProductionRuntimeDebug));
    }

    #[test]
    fn same_plan_freezes_same_schedule_and_fixture_identity() {
        let first = BenchmarkCampaign::new(plan()).expect("campaign");
        let second = BenchmarkCampaign::new(plan()).expect("campaign");
        assert_eq!(first.plan_fingerprint, second.plan_fingerprint);
        assert_eq!(first.runs, second.runs);
        assert_eq!(
            first
                .plan
                .tasks
                .iter()
                .map(|task| task.fixture.instance_id.clone())
                .collect::<Vec<_>>(),
            second
                .plan
                .tasks
                .iter()
                .map(|task| task.fixture.instance_id.clone())
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn model_comparison_interleaves_candidates_by_task_and_repetition() {
        let campaign = BenchmarkCampaign::new(plan()).expect("campaign");
        let first = &campaign.runs[..4];
        assert_eq!(first[0].schedule.candidate_index, 0);
        assert_eq!(first[1].schedule.candidate_index, 1);
        assert_eq!(first[2].schedule.candidate_index, 0);
        assert_eq!(first[3].schedule.candidate_index, 1);
        assert!(first
            .iter()
            .all(|run| run.schedule.task_id == "read_question_v1"));
    }

    #[test]
    fn exact_download_approval_cannot_authorize_an_extra_candidate() {
        let mut plan = plan();
        plan.candidates[0].source = CampaignCandidateSource {
            source_reference: Some("https://models.example/model-a.gguf".to_owned()),
            license: Some("Apache-2.0".to_owned()),
            expected_sha256: Some(plan.candidates[0].representation.model_version.clone()),
            transfer_size_bytes: Some(4_000_000_000),
            storage_size_bytes: Some(4_000_000_000),
        };
        let campaign = BenchmarkCampaign::new(plan).expect("campaign");
        let preflight = campaign
            .preflight(&[campaign.plan.candidates[1].representation.clone()])
            .expect("preflight");
        let mut approval = CampaignDownloadApproval::exact(&preflight);
        approval
            .approved_missing
            .push(campaign.plan.candidates[1].representation.clone());
        assert!(campaign
            .validate_download_approval(&preflight, &approval)
            .is_err());
    }

    #[test]
    fn runtime_characterization_requires_same_model_on_both_windows_environments() {
        let mut plan = plan();
        plan.candidates.truncate(1);
        plan.comparison_class = CampaignComparisonClass::RuntimeCharacterization;
        plan.execution_environments = vec![
            CampaignEnvironmentIdentity {
                environment: CampaignExecutionEnvironment::WindowsNative,
                backend_runtime_version: "llama.cpp:b1@rev;env=windows_native".to_owned(),
            },
            CampaignEnvironmentIdentity {
                environment: CampaignExecutionEnvironment::Wsl2Linux,
                backend_runtime_version: "llama.cpp:b1@rev;env=wsl2_linux".to_owned(),
            },
        ];
        assert!(plan.validate().is_ok());
        plan.candidates.push(candidate("model-b"));
        assert!(plan.validate().is_err());
    }

    #[test]
    fn profile_and_environment_change_campaign_identity() {
        let warm = plan().fingerprint().expect("warm");
        let mut changed = plan();
        changed.execution_profile = CampaignExecutionProfile::Cold;
        assert_ne!(warm, changed.fingerprint().expect("cold"));
        let mut changed = plan();
        changed.execution_environments[0].backend_runtime_version.push_str("-new");
        assert_ne!(warm, changed.fingerprint().expect("runtime changed"));
    }

    #[test]
    fn bounded_retry_exists_only_before_measurement() {
        let mut campaign = BenchmarkCampaign::new(plan()).expect("campaign");
        let verified = campaign
            .plan
            .candidates
            .iter()
            .map(|candidate| candidate.representation.clone())
            .collect::<Vec<_>>();
        campaign.start(&verified).expect("start");
        for attempt in 0..=MAX_PRE_MEASUREMENT_RETRIES {
            let request = campaign.begin_next_run().expect("begin").expect("request");
            let disposition = campaign
                .record_pre_measurement_failure(&request)
                .expect("failure");
            if attempt < MAX_PRE_MEASUREMENT_RETRIES {
                assert_eq!(disposition, PreMeasurementFailureDisposition::Retry);
            } else {
                assert_eq!(disposition, PreMeasurementFailureDisposition::Exhausted);
            }
        }
        let next = campaign.begin_next_run().expect("begin measured").expect("request");
        campaign
            .mark_measurement_started(&next)
            .expect("measurement start");
        assert!(campaign.record_pre_measurement_failure(&next).is_err());
    }

    #[test]
    fn resume_rejects_hardware_runtime_model_or_fixture_drift() {
        let mut campaign = BenchmarkCampaign::new(plan()).expect("campaign");
        let verified = campaign
            .plan
            .candidates
            .iter()
            .map(|candidate| candidate.representation.clone())
            .collect::<Vec<_>>();
        campaign.start(&verified).expect("start");
        campaign.pause().expect("pause");
        let mut current = campaign.plan.resume_identity();
        current.hardware.platform.push_str("-changed");
        assert!(campaign.resume(current).is_err());
        assert_eq!(campaign.state, BenchmarkCampaignState::Incompatible);
    }

    #[test]
    fn candidate_contract_does_not_contain_host_oracle_material() {
        let fixture = CampaignFixtureIdentity::for_task("code_implementation_v1", 42);
        let contract = fixture
            .candidate_contract("code_implementation_v1")
            .expect("contract");
        let json = serde_json::to_string(&contract).expect("serialize");
        assert!(!json.contains("host-only"));
        assert!(!json.contains("golden"));
        assert!(!json.contains("answer key"));
        assert!(!json.contains("hidden_token"));
    }
